import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import UnifiedNavbar from "../components/UnifiedNavbar";
import API from "../services/api";
import attendanceService from "../services/attendanceService";

function AdminDashboard(){
  const [stats, setStats] = useState({
    totalStudents: 0,
    totalMenus: 0,
    todayPresent: 0,
    todayAbsent: 0,
    todayLeave: 0
  });
  const [students, setStudents] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [selectedStatus, setSelectedStatus] = useState(null);
  const [showStudentList, setShowStudentList] = useState(false);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      
      // Fetch total students
      const studentsRes = await API.get("/student");
      const studentsList = studentsRes.data || [];
      setStudents(studentsList);

      // Fetch today's attendance
      const today = new Date().toISOString().split('T')[0];
      const attendanceData = await attendanceService.getAttendance({
        date: today
      });
      const todayAttendance = Array.isArray(attendanceData) ? attendanceData : [];
      setAttendance(todayAttendance);

      const newStats = {
        totalStudents: studentsList.length,
        totalMenus: 0,
        todayPresent: todayAttendance.filter(a => a.status === "Present").length,
        todayAbsent: todayAttendance.filter(a => a.status === "Absent").length,
        todayLeave: todayAttendance.filter(a => a.status === "Leave").length
      };

      // Try to fetch menus
      try {
        const menusRes = await API.get("/menu");
        newStats.totalMenus = menusRes.data?.length || 0;
      } catch (e) {
        newStats.totalMenus = 0;
      }

      setStats(newStats);
    } catch (error) {
      console.log("Error fetching stats");
    }
  };

  const getStudentsByStatus = (status) => {
    if (status === "all") {
      return students;
    }
    return students.filter(student => {
      const record = attendance.find(a => a.studentId === student.id);
      if (status === "unmarked") {
        return !record;
      }
      return record?.status === status;
    });
  };

  const handleStatCardClick = (status) => {
    setSelectedStatus(status);
    setShowStudentList(true);
  };

  return(
    <div className="dashboard">
      <UnifiedNavbar />
      <div className="main-content">
        <h1>Admin Dashboard</h1>
        
        {!showStudentList ? (
          <>
            <div className="stats-overview">
              <div className="stat-card" style={{ cursor: "pointer" }} onClick={() => handleStatCardClick("all")}>
                <span className="stat-icon">👥</span>
                <div className="stat-info">
                  <span className="stat-value">{stats.totalStudents}</span>
                  <span className="stat-label">Total Students</span>
                </div>
              </div>
              <div className="stat-card" style={{ cursor: "pointer" }} onClick={() => handleStatCardClick("Present")}>
                <span className="stat-icon">✓</span>
                <div className="stat-info">
                  <span className="stat-value">{stats.todayPresent}</span>
                  <span className="stat-label">Present Today</span>
                </div>
              </div>
              <div className="stat-card" style={{ cursor: "pointer" }} onClick={() => handleStatCardClick("Absent")}>
                <span className="stat-icon">✗</span>
                <div className="stat-info">
                  <span className="stat-value">{stats.todayAbsent}</span>
                  <span className="stat-label">Absent Today</span>
                </div>
              </div>
              <div className="stat-card" style={{ cursor: "pointer" }} onClick={() => handleStatCardClick("Leave")}>
                <span className="stat-icon">📋</span>
                <div className="stat-info">
                  <span className="stat-value">{stats.todayLeave}</span>
                  <span className="stat-label">Leave Today</span>
                </div>
              </div>
            </div>

            <div className="cards">
              <div className="card">
                <h3>Student List</h3>
                <p>View all registered students</p>
                <Link to="/students" className="card-link">View Students</Link>
              </div>

              <div className="card">
                <h3>Manage Menu</h3>
                <p>Create, edit, and manage daily menus</p>
                <Link to="/edit-menu" className="card-link">Manage Menu</Link>
              </div>

              <div className="card">
                <h3>Attendance Management</h3>
                <p>Track and manage student attendance</p>
                <Link to="/attendance" className="card-link">View Attendance</Link>
              </div>
            </div>
          </>
        ) : (
          <div className="student-list-view">
            <button 
              onClick={() => setShowStudentList(false)}
              style={{
                padding: "8px 16px",
                marginBottom: "20px",
                backgroundColor: "#6B7280",
                color: "white",
                border: "none",
                borderRadius: "6px",
                cursor: "pointer"
              }}
            >
              ← Back to Dashboard
            </button>
            
            <div className="student-list-header">
              <h2>
                {selectedStatus === "all" && "All Students"}
                {selectedStatus === "Present" && "✓ Present Today"}
                {selectedStatus === "Absent" && "✗ Absent Today"}
                {selectedStatus === "Leave" && "📋 Leave Today"}
              </h2>
              <p className="count-badge">{getStudentsByStatus(selectedStatus).length} students</p>
            </div>

            <div className="students-table">
              <table className="table">
                <thead>
                  <tr>
                    <th>Student ID</th>
                    <th>Student Name</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {getStudentsByStatus(selectedStatus).map(student => {
                    const attendanceRecord = attendance.find(a => a.studentId === student.id);
                    return (
                      <tr key={student.id}>
                        <td>{student.id}</td>
                        <td>{student.name}</td>
                        <td>
                          <span className={`status-badge ${attendanceRecord?.status?.toLowerCase() || "unmarked"}`}>
                            {attendanceRecord?.status || "Not Marked"}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
  </div>
  );
}

export default AdminDashboard
